try{kalite_filo_admin_require_method('GET');kalite_filo_admin_start_session();kalite_filo_admin_require_authentication();$id=(string)($_GET['id']??'');$download=($_GET['download']??'')==='1';$media=null;$path=null;foreach(kalite_filo_admin_article_media_records() as $candidate)if(($candidate['id']??null)===$id){$media=$candidate;$path=kalite_filo_admin_article_media_path($id,(string)$candidate['extension']);break;}if(!is_array($media))foreach(kalite_filo_admin_vehicle_records() as $record){$gallery=is_array($record['galleryMedia']??null)?$record['galleryMedia']:(is_array($record['draftMedia']??null)?[$record['draftMedia']]:[]);foreach($gallery as $candidate)if(is_array($candidate)&&($candidate['id']??null)===$id){$media=$candidate;$path=kalite_filo_admin_vehicle_media_path($id,(string)$candidate['extension']);break 2;}}if(!is_array($media)||!is_string($path)||!is_file($path)||is_link($path))kalite_filo_admin_json(['error'=>'not_found'],404);header('Content-Type: '.(string)$media['mime']);header('Content-Length: '.filesize($path));header('X-Content-Type-Options: nosniff');if($download){$name=preg_replace('/[^A-Za-z0-9._-]/','-',basename((string)($media['originalName']??'image.webp')))?:'image.webp';header('Content-Disposition: attachment; filename="'.$name.'"');}readfile($path);exit;}catch(Throwable $e){error_log('Admin image file failed: '.$e->getMessage());kalite_filo_admin_json(['error'=>'service_unavailable'],503);}
